 public static readonly List<string> Results=new List<string>();public static bool Finished;static int failed;
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static object Get(DungeonPrototype d,string field){return typeof(DungeonPrototype).GetField(field,Flags).GetValue(d);}
