 public static void Start(){Results.Clear();failed=0;Finished=false;EditorApplication.isPaused=false;Time.timeScale=1;var lab=UnityEngine.Object.FindAnyObjectByType<CombatLaboratory>();lab.enabled=false;var d=lab.GetComponent<DungeonPrototype>();d.enabled=false;new GameObject("Makong balance verification").AddComponent<CombatTestRunner>().StartCoroutine(Run(lab,d));}
 static IEnumerator Run(CombatLaboratory lab,DungeonPrototype d){
  var settings=MakongSpecialSettings.Current;var profile=EnemyCharacterCatalog.Current.FindId("Makong");var effective=EnemyLevelSettings.Current.Evaluate(profile,10);Check(effective.maximumHP==210&&effective.damage==13&&effective.defense==9&&effective.luck==6&&effective.specialDamage==16,"Estadísticas finales exigentes de Makong LV10 sin doble escalado");
  var state=new MakongTactics();int lastQuake=-100,lastEat=-100,eats=0;MakongAction previous=MakongAction.Normal;for(int turn=0;turn<40;turn++){var action=state.Decide(new MakongContext{hp=1,maximumHP=210,helpers=2,participants=3,edibleHelper=true,canSummon=true},settings,()=>0);if(action==MakongAction.Earthquake){Check(state.Turn-lastQuake>settings.earthquakeCooldownTurns,"Cooldown terremoto turno "+state.Turn);lastQuake=state.Turn;}if(action==MakongAction.Swallow){Check(state.Turn-lastEat>settings.swallowCooldownTurns,"Cooldown devorar turno "+state.Turn);lastEat=state.Turn;eats++;}Check(!(previous==MakongAction.Summon&&action==MakongAction.Swallow||previous==MakongAction.Swallow&&action==MakongAction.Summon),"Sin cadena invocar/devorar turno "+state.Turn);previous=action;}
  Check(eats==2&&state.Swallows==2,"Devorar: máximo dos usos por combate");var fresh=new MakongTactics();Check(!fresh.CanUse(MakongAction.Swallow,new MakongContext{hp=100,maximumHP=210,edibleHelper=true},settings,1),"No devora con HP alto");Check(!fresh.CanUse(MakongAction.Swallow,new MakongContext{hp=1,maximumHP=210,edibleHelper=false},settings,1),"No devora sin ayudantes");Check(!fresh.CanUse(MakongAction.Summon,new MakongContext{hp=200,maximumHP=210,helpers=2,participants=3,canSummon=true},settings,1),"Límite dos ayudantes y tres participantes");Check(!fresh.CanUse(MakongAction.Summon,new MakongContext{hp=1,maximumHP=210,helpers=0,participants=1,canSummon=true},settings,1),"No fabrica ayudantes para curarse con HP bajo");
  // Restore the original introduction through the real NEW GAME command.
  typeof(DungeonPrototype).GetMethod("StartFreshFromMenu",Flags).Invoke(d,null);Check((bool)typeof(DungeonPrototype).GetProperty("IntroductionActive",Flags).GetValue(d),"Nueva partida inicia diálogos originales de GamerBoy");d.InitializeLaboratory();
  lab.gamerLevel=10;d.ResetLaboratory(10);var originalMap=d.mapSettings;var data=d.CaptureDungeonSave();data.player.inventory.Clear();var character=Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings");foreach(var id in character.initialEquipmentIds)data.player.inventory.Add(new InventoryItemRecord{itemId=id,quantity=1});data.player.equipmentIds=(string[])character.initialEquipmentIds.Clone();data.enemies.Clear();data.player.currentHP=int.MaxValue;d.RestoreDungeonSave(data);
  var clone=ScriptableObject.CreateInstance<DungeonMapSettings>();JsonUtility.FromJsonOverwrite(JsonUtility.ToJson(originalMap),clone);var objects=ScriptableObject.CreateInstance<DungeonEntitySettings>();for(int n=0;n<3;n++)objects.objects.Add(new DungeonMapEntity{id="makong.test.chest."+n,kind=DungeonEntityKind.Chest,cell=new Vector2Int(3+n*2,4),contentId=MakongBalanceSetup.EquipmentIds[n],quantity=1});clone.entities=objects;d.mapSettings=clone;typeof(DungeonPrototype).GetMethod("CreateMapEntities",Flags).Invoke(d,null);
  int[] initialStats=d.PlayerStatValues;for(int n=0;n<3;n++){typeof(DungeonPrototype).GetMethod("InteractMapEntity",Flags).Invoke(d,new object[]{objects.objects[n]});yield return new WaitForSecondsRealtime(.8f);}Check(d.PlayerStatValues[1]==initialStats[1],"Recibir los tres equipos no los equipa automáticamente");foreach(var id in MakongBalanceSetup.EquipmentIds)Check(d.EquipItem(id),"Objeto equipable real "+id);var actual=d.PlayerStatValues;Check(actual[0]==66&&actual[1]==17&&actual[2]==15&&actual[3]==14,"GamerBoy LV10 con equipo nuevo: HP66 ATK17 DEF15 LUK14");
  // A real encounter exercises summons, quake and swallow through the shared action routines.
  lab.speciesId="Makong";lab.enemyLevel=10;lab.companions=0;lab.equipmentPreset=3;lab.Fight();yield return new WaitForSecondsRealtime(.9f);var group=(List<int>)Get(d,"encounter");var enemies=(List<GameObject>)Get(d,"enemyObjects");var lives=(List<int>)Get(d,"enemyLives");int boss=group[0];var visual=enemies[boss].GetComponent<MakongEnemyVisual>();var context=new MakongContext{hp=210,maximumHP=210,helpers=0,participants=1,canSummon=true};Check(visual.Tactics.TryManual(MakongAction.Summon,context,settings),"Inicio de llamada válido");float originalDouble=settings.twoHelpersProbability;settings.twoHelpersProbability=1;yield return Call(d,"RunMakongAction",boss,visual,MakongAction.Summon);settings.twoHelpersProbability=originalDouble;
  Check(group.Count==3,"Invocación crea dos ayudantes y respeta capacidad");foreach(int index in group)if(index!=boss){var stats=enemies[index].GetComponent<EnemyCombatStats>();Check(stats.level<10&&enemies[index].GetComponent<MakongSummonedHelper>()!=null,"Ayudante existente, débil y de nivel inferior");Check(((List<float>)Get(d,"respawnAt"))[index]<0,"Ayudante sin respawn permanente");}Check(d.CaptureEnemyProgression().Count==1,"Ayudantes invocados excluidos del guardado de población");
  visual.Tactics.Decide(new MakongContext{hp=210,maximumHP=210,helpers=2,participants=3,edibleHelper=false},settings,()=>0);Check(visual.Tactics.TryManual(MakongAction.Earthquake,new MakongContext{hp=210,maximumHP=210,helpers=2,participants=3},settings),"Terremoto válido tras un turno normal");var snapshot=enemies[boss].GetComponent<EnemyCombatStats>().snapshot;snapshot.specialMissPercent=snapshot.normalMissPercent=snapshot.criticalPercent=0;snapshot.luck=0;int beforeHP=(int)Get(d,"hp");yield return Call(d,"RunMakongAction",boss,visual,MakongAction.Earthquake);int expected=CombatMath.Damage(16,d.PlayerStatValues[2],1,false,1,CombatBalanceSettings.Current);Check(beforeHP-(int)Get(d,"hp")==expected,"Terremoto usa CombatMath y defensa, daño único");Check(d.GetComponentInChildren<CombatImpactFeedback>().Active,"Caída activa sacudida");
  visual.Tactics.Decide(new MakongContext{hp=50,maximumHP=210,helpers=2,participants=3,edibleHelper=true},settings,()=>0);lives[boss]=50;context=new MakongContext{hp=50,maximumHP=210,helpers=2,participants=3,edibleHelper=true};Check(visual.Tactics.TryManual(MakongAction.Swallow,context,settings),"Devorar válido con HP bajo y ayudante antiguo");yield return Call(d,"RunMakongAction",boss,visual,MakongAction.Swallow);yield return null;Check(lives[boss]==68,"Devorar cura exactamente 18 HP");Check(group.Count==2,"Ayudante consumido eliminado realmente");Check((int)Get(d,"encounterXP")==0&&(int)Get(d,"encounterDefeats")==0,"Consumido no entrega XP ni drops de derrota del jugador");Check(d.GetComponentsInChildren<MakongTongueVisual>().Length==0,"Lengua separada se limpia al terminar");
  var accuracy=ScriptableObject.CreateInstance<CombatAccuracySettings>();accuracy.enabledLuck=false;d.attackAccuracySettings=accuracy;int helper=group.Find(i=>i!=boss);var helperStats=enemies[helper].GetComponent<EnemyCombatStats>();int helperReward=PlayerLevelSettings.Current.Reward(helperStats.level,10,PlacedEnemyCategory.Normal);Set(d,"activeEnemy",helper);yield return Call(d,"ResolveCombatDamage",999,"ATTACK");Check((int)Get(d,"encounterXP")==helperReward&&helperReward>0,"Ayudante derrotado por GamerBoy da XP normal una sola vez");Check((int)Get(d,"encounterDefeats")==1,"Ayudante derrotado por jugador registra drops");Set(d,"activeEnemy",boss);long previousXP=d.PlayerExperience;yield return Call(d,"ResolveCombatDamage",999,"ATTACK");Check(!d.LaboratoryBattle&&d.PlayerExperience-previousXP==helperReward+PlayerLevelSettings.Current.Reward(10,10,PlacedEnemyCategory.Elite),"Victoria paga XP de subjefe y ayudante, excluyendo consumido");Check(((HashSet<int>)Get(d,"combatSummons")).Count==0,"Victoria limpia población temporal");
  string oldSavePath=DungeonSaveStore.editorTestPath;DungeonSaveStore.editorTestPath=System.IO.Path.GetFullPath("Tests/MakongBalanceSaveFixture.json");Check(d.SaveDungeonGame(),"Guardar equipo y cofres en fixture aislado");Check(d.LoadDungeonGame(),"Cargar fixture");var captured=d.CaptureDungeonSave();Check(Array.TrueForAll(MakongBalanceSetup.EquipmentIds,id=>Array.IndexOf(captured.player.equipmentIds,id)>=0),"Equipo nuevo persiste al cargar");int inventoryBefore=captured.player.inventory.Count;foreach(var chest in objects.objects)typeof(DungeonPrototype).GetMethod("InteractMapEntity",Flags).Invoke(d,new object[]{chest});yield return new WaitForSecondsRealtime(.9f);Check(d.CapturePlayerProgression().inventory.Count==inventoryBefore&&captured.entityStates.TrueForAll(e=>e.opened),"Cofres abiertos no repiten sus objetos tras carga");DungeonSaveStore.editorTestPath=oldSavePath;
  var jump=d.GetComponent<EnemyJumpHack>();jump.ConfigureAttack(d.PlayerStatValues[1],9);Check(!jump.UsesAttackLuck&&Resources.Load<Texture2D>("UI/JumpEnemies/Makong_0")!=null,"JUMP conserva fórmula y recursos de Makong");var overclock=d.GetComponent<OverclockHack>();Check(overclock!=null&&PlayerHackCatalog.Current!=null,"OVERCLOCK continúa disponible a nivel 10");
  foreach(var root in ((Dictionary<string,GameObject>)Get(d,"mapEntityObjects")).Values)if(root!=null)UnityEngine.Object.Destroy(root);((Dictionary<string,GameObject>)Get(d,"mapEntityObjects")).Clear();d.mapSettings=originalMap;d.attackAccuracySettings=null;UnityEngine.Object.Destroy(clone);UnityEngine.Object.Destroy(objects);UnityEngine.Object.Destroy(accuracy);lab.Choose();lab.enabled=true;d.enabled=true;Results.Add("TOTAL "+(Results.Count-failed)+" PASS / "+failed+" FAIL");System.IO.File.WriteAllLines("Tests/MakongBalanceMcpResults.txt",Results);Finished=true;Debug.Log(Results[Results.Count-1]);
 }
}
